"""The per-owner file count limit on creating an auto-generated file, run against a real database."""

from __future__ import annotations

import uuid
from collections.abc import AsyncGenerator

import pytest
import sqlalchemy as sa

from ai.backend.common.data.entity.user import UserEntityType, UserID
from ai.backend.manager.data.dotfile.types import MAXIMUM_DOTFILE_COUNT, DotfileEntry
from ai.backend.manager.errors.storage import DotfileCreationFailed
from ai.backend.manager.models.auto_generated_file.creators import AutoGeneratedFileCreator
from ai.backend.manager.models.auto_generated_file.row import AutoGeneratedFileRow
from ai.backend.manager.models.utils import ExtendedAsyncSAEngine
from ai.backend.manager.models.virtual_entity.entity_membership import EntityMembershipRow
from ai.backend.manager.models.virtual_entity.entity_membership_cap import (
    EntityMembershipCapRow,
)
from ai.backend.manager.models.virtual_entity.entity_membership_field import (
    EntityMembershipFieldRow,
)
from ai.backend.manager.models.virtual_entity.scope_binding import ScopeBindingRow
from ai.backend.manager.models.virtual_entity.virtual_entity import VirtualEntityRow
from ai.backend.manager.repositories.ops.v2.provider import V2DBOpsProvider
from ai.backend.testutils.db import with_tables

_ENTRY = DotfileEntry(path=".bashrc", perm="644", data="")


class TestCreateAutoGeneratedFile:
    @pytest.fixture
    async def db(
        self, database_connection: ExtendedAsyncSAEngine
    ) -> AsyncGenerator[ExtendedAsyncSAEngine, None]:
        async with with_tables(
            database_connection,
            [
                VirtualEntityRow,
                EntityMembershipRow,
                EntityMembershipCapRow,
                EntityMembershipFieldRow,
                ScopeBindingRow,
                AutoGeneratedFileRow,
            ],
        ):
            yield database_connection

    @pytest.fixture
    async def user_id(self, db: ExtendedAsyncSAEngine) -> UserID:
        user_id = UserID(uuid.uuid4())
        async with db.begin_session() as session:
            session.add(VirtualEntityRow(entity_type=UserEntityType(), entity_id=user_id))
        return user_id

    @pytest.fixture
    async def user_at_limit(self, db: ExtendedAsyncSAEngine, user_id: UserID) -> UserID:
        row = {
            "entity_type": UserEntityType(),
            "entity_id": user_id,
            "path": _ENTRY.path,
            "perm": _ENTRY.perm,
            "data": _ENTRY.data,
        }
        async with db.begin_session() as session:
            await session.execute(sa.insert(AutoGeneratedFileRow), [row] * MAXIMUM_DOTFILE_COUNT)
        return user_id

    @pytest.fixture
    async def other_user_id(self, db: ExtendedAsyncSAEngine) -> UserID:
        user_id = UserID(uuid.uuid4())
        async with db.begin_session() as session:
            session.add(VirtualEntityRow(entity_type=UserEntityType(), entity_id=user_id))
        return user_id

    async def test_owner_at_the_limit_is_refused(
        self,
        db: ExtendedAsyncSAEngine,
        user_at_limit: UserID,
    ) -> None:
        with pytest.raises(DotfileCreationFailed):
            async with V2DBOpsProvider(db).write_ops() as w:
                await w.create_entity(AutoGeneratedFileCreator(owner=user_at_limit, entry=_ENTRY))

        async with db.begin_readonly_session() as session:
            count = await session.scalar(
                sa.select(sa.func.count()).select_from(AutoGeneratedFileRow)
            )
        assert count == MAXIMUM_DOTFILE_COUNT

    async def test_other_owners_files_do_not_count(
        self,
        db: ExtendedAsyncSAEngine,
        user_at_limit: UserID,
        other_user_id: UserID,
    ) -> None:
        async with V2DBOpsProvider(db).write_ops() as w:
            data = await w.create_entity(
                AutoGeneratedFileCreator(owner=other_user_id, entry=_ENTRY)
            )

        assert data.path == _ENTRY.path
